select count(*) from vm_flow_template t1


		AND t1.template_id != #{flowId}


		AND (t1.tenant_id = #{tenantId}

			AND t1.industry_code = #{industryCode}


			AND t1.app_ver_code = #{appVerCode}

		or t1.template_id in (
		select template_id from vm_flow_template_industry
		where delete_flag = 0 and app_ver_code = #{appVerCode}
		and industry_code = #{industryCode}))


		AND t1.flow_name = #{flowName}

	AND t1.status = '1' AND t1.delete_flag = 0

